      {
        "point": "Examine the email's metadata including From, To fields, and subject line to identify internal vs. external senders"
      },
      {
        "point": "Analyze the email body for content related to core business operations like crew scheduling, HR processes, financial matters, or operational planning"
      },
      {
        "point": "Identify legitimate business communications that require processing or attention from staff"
      },
      {
        "point": "Recognize automated system notifications, delivery failures, and non-actionable communications"
      },
      {
        "point": "Consider security indicators such as 'EXTERNAL Email' warnings in determining classification"
      },
      {
        "point": "Evaluate email domains to distinguish between internal company domains and external vendors/partners"
      },
      {
        "point": "Determine if external communications are from legitimate business partners requiring internal processing"
      }
