                "point": "Port scheduling, arrival/departure coordination, or itinerary changes"
              },
              {
                "point": "Internal announcements about operational milestones or changes"
              },
              {
                "point": "Cross-departmental coordination for business activities"
              }
            ]
          }
        ]
      },
